CREATE TABLE schools (id TEXT PRIMARY KEY, name TEXT NOT NULL, lga TEXT NOT NULL, address TEXT, contact_phone TEXT, principal_name TEXT, email TEXT UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP); CREATE TABLE users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), school_id TEXT, username TEXT UNIQUE NOT NULL, email TEXT UNIQUE, password_hash TEXT NOT NULL, full_name TEXT, role TEXT DEFAULT 'SCHOOL_STAFF', is_active BOOLEAN DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (school_id) REFERENCES schools(id)); CREATE TABLE students (id TEXT PRIMARY KEY, school_id TEXT NOT NULL, first_name TEXT NOT NULL, last_name TEXT NOT NULL, date_of_birth DATE, gender TEXT, town TEXT, photo_url TEXT, registration_year INT, status TEXT DEFAULT 'ACTIVE', duplicate_of TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (school_id) REFERENCES schools(id)); CREATE TABLE subjects (id TEXT PRIMARY KEY, name TEXT NOT NULL, code TEXT UNIQUE, max_ca_score INT DEFAULT 30, max_exam_score INT DEFAULT 70); CREATE TABLE scores (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), student_id TEXT NOT NULL, subject_id TEXT NOT NULL, ca_score DECIMAL(5,2), exam_score DECIMAL(5,2), total_score DECIMAL(5,2), grade TEXT, term INT, year INT, source_school_id TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (student_id) REFERENCES students(id), FOREIGN KEY (subject_id) REFERENCES subjects(id), FOREIGN KEY (source_school_id) REFERENCES schools(id)); CREATE TABLE sync_logs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), school_id TEXT NOT NULL, user_id UUID, total_records INT, successful_records INT, failed_records INT, error_details JSON, synced_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (school_id) REFERENCES schools(id), FOREIGN KEY (user_id) REFERENCES users(id)); CREATE TABLE audit_logs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID, action TEXT, table_name TEXT, record_id TEXT, old_data JSONB, new_data JSONB, ip_address INET, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id)); CREATE INDEX idx_students_school_id ON students(school_id); CREATE INDEX idx_students_year ON students(registration_year); CREATE INDEX idx_scores_student_id ON scores(student_id); CREATE INDEX idx_scores_year_term ON scores(year, term); CREATE INDEX idx_sync_logs_school ON sync_logs(school_id, synced_at); CREATE INDEX idx_audit_logs_user ON audit_logs(user_id, created_at);